BUSINESS_HTML=r'''<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#07111f"><title>Panther Peptides Command Center</title><style>:root{--bg:#050b13;--panel:#0b1727;--panel2:#0f2035;--line:#203c59;--text:#f2f7fc;--muted:#8ea8c1;--blue:#438dff;--green:#39d49d;--amber:#f2b84b;--red:#ff7185}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 50% -20%,#17375c 0,#07111f 35%,#040910 100%);color:var(--text);font:15px system-ui,-apple-system,sans-serif;min-height:100vh}.wrap{max-width:1540px;margin:auto;padding:22px}.top{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:18px}.brand{display:flex;align-items:center;gap:14px}.logo{width:46px;height:46px;border-radius:14px;background:linear-gradient(135deg,#3f91ff,#53dfc0);display:grid;place-items:center;font-weight:900;color:#06101d}.brand h1{font-size:22px;margin:0}.brand small,.muted{color:var(--muted)}.nav{display:flex;gap:8px}.btn{border:1px solid #2d4c6c;background:#10223a;color:#eaf4ff;padding:11px 14px;border-radius:12px;font-weight:750;cursor:pointer;text-decoration:none}.btn.primary{background:linear-gradient(135deg,#327fff,#4c9cff);border:0}.btn.green{background:#123c33;border-color:#236d59;color:#c9f8e7}.btn.red{background:#421a24;border-color:#773242}.banner{border:1px solid #72571c;background:#2a200c;color:#ffd776;padding:11px 15px;border-radius:13px;margin-bottom:18px}.metrics{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin-bottom:18px}.metric,.card{background:linear-gradient(180deg,rgba(15,32,53,.98),rgba(9,22,38,.98));border:1px solid var(--line);border-radius:18px;box-shadow:0 18px 50px rgba(0,0,0,.18)}.metric{padding:17px}.metric b{display:block;font-size:27px;margin-top:6px}.metric span{color:var(--muted);font-size:13px}.grid{display:grid;grid-template-columns:minmax(0,1.65fr) minmax(330px,.7fr);gap:18px}.card{padding:20px}.card h2{margin:0 0 6px;font-size:20px}.head{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-bottom:16px}.tablewrap{overflow:auto;border:1px solid #1f3852;border-radius:14px}table{width:100%;border-collapse:collapse;min-width:900px}th,td{text-align:left;padding:12px;border-bottom:1px solid #1d354e;vertical-align:top}th{font-size:12px;text-transform:uppercase;letter-spacing:.07em;color:#91acc6;background:#0a1727;position:sticky;top:0}td{color:#e8f1fa}.pill{display:inline-block;border:1px solid #31516f;border-radius:999px;padding:5px 9px;font-size:12px}.pill.quarantine,.pill.hold,.pill.blocked{color:#ffd278;border-color:#76591e;background:#2b210d}.pill.released,.pill.approved{color:#bdf5df;border-color:#286b59;background:#0d2b24}.pill.pending_review{color:#a8d3ff}.drop{border:1px dashed #3a6082;border-radius:12px;padding:10px;background:#081522}.drop input{max-width:220px}.stack{display:flex;flex-direction:column;gap:12px}.event{padding:12px;border:1px solid #203b57;border-radius:13px;background:#091725}.event b{display:block;margin-bottom:4px}.event small{color:var(--muted)}.empty{padding:36px;text-align:center;color:var(--muted)}.notice{color:var(--muted);line-height:1.45}.modal{position:fixed;inset:0;background:rgba(0,0,0,.7);display:none;place-items:center;padding:20px}.modal.on{display:grid}.modalbox{width:min(600px,100%);background:#0d1c30;border:1px solid #31506d;border-radius:18px;padding:22px}.modalbox h3{margin-top:0}.actions{display:flex;gap:8px;flex-wrap:wrap}.login{max-width:520px;margin:14vh auto}.login input{width:100%;padding:14px;border-radius:12px;border:1px solid #31506d;background:#06111e;color:#fff}.hidden{display:none!important}@media(max-width:1000px){.metrics{grid-template-columns:repeat(2,1fr)}.grid{grid-template-columns:1fr}.wrap{padding:12px}.top{align-items:flex-start}.nav{flex-wrap:wrap;justify-content:flex-end}}@media(max-width:600px){.metrics{grid-template-columns:1fr 1fr}.brand small{display:none}.metric b{font-size:22px}}</style></head><body><div class="wrap"><div class="top"><div class="brand"><div class="logo">PP</div><div><h1>Panther Peptides Command Center</h1><small>Jarvis Business Operations</small></div></div><div class="nav"><a class="btn" href="/">Jarvis</a><button class="btn" onclick="load()">Refresh</button></div></div><div class="banner">FOR RESEARCH USE ONLY — NOT FOR HUMAN OR VETERINARY USE · Inventory remains quarantined until supporting evidence is uploaded, reviewed, and explicitly released.</div><div id="login" class="card login hidden"><h2>Owner Access</h2><p class="notice">Sign in through Jarvis first, then return to the dashboard.</p><a class="btn primary" href="/">Open Jarvis</a></div><main id="app"><div class="metrics"><div class="metric"><span>Inventory lots</span><b id="lots">—</b></div><div class="metric"><span>Total units</span><b id="units">—</b></div><div class="metric"><span>Quarantined units</span><b id="quarantine">—</b></div><div class="metric"><span>Released units</span><b id="released">—</b></div><div class="metric"><span>Lots needing documents</span><b id="missing">—</b></div></div><div class="grid"><section class="card"><div class="head"><div><h2>Inventory Control</h2><div class="notice">Lot-level evidence, review and release workflow.</div></div><button id="importBtn" class="btn" onclick="importLegacy()">Recover legacy inventory</button></div><div class="tablewrap"><table><thead><tr><th>Product</th><th>Lot / SKU</th><th>Qty</th><th>Status</th><th>Evidence</th><th>Documents / action</th></tr></thead><tbody id="inventory"></tbody></table></div></section><aside class="stack"><section class="card"><h2>Jarvis Operations</h2><p id="runtime" class="notice">Loading…</p><div id="objectives"></div></section><section class="card"><h2>Recent Business Activity</h2><div id="events"></div></section></aside></div></main></div><div id="reviewModal" class="modal"><div class="modalbox"><h3>Document Review</h3><p id="reviewText" class="notice"></p><div class="actions"><button class="btn green" id="approveBtn">Approve evidence</button><button class="btn red" id="rejectBtn">Reject</button><button class="btn" onclick="closeModal()">Cancel</button></div><p class="notice">Approval records the document as accepted evidence. Inventory is still not released until you explicitly select Release lot.</p></div></div><script>const $=id=>document.getElementById(id);let data=null;async function api(url,opt={}){const r=await fetch(url,{...opt,cache:'no-store'}),d=await r.json().catch(()=>({}));if(r.status===401){$('login').classList.remove('hidden');$('app').classList.add('hidden');throw new Error('Owner login required')}if(!r.ok)throw new Error(d.detail||d.error||`HTTP ${r.status}`);return d}function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function pill(s){return `<span class="pill ${esc(String(s).toLowerCase())}">${esc(s)}</span>`}async function load(){try{data=await api('/business/dashboard');$('login').classList.add('hidden');$('app').classList.remove('hidden');let s=data.summary;$('lots').textContent=s.lots;$('units').textContent=s.units;$('quarantine').textContent=s.quarantined_units;$('released').textContent=s.released_units;$('missing').textContent=s.lots_missing_or_unknown_docs;renderInventory();renderOps();renderEvents()}catch(e){console.error(e)}}function renderInventory(){let rows=data.inventory||[];$('inventory').innerHTML=rows.length?rows.map(x=>{let docs=(x.documents||[]).map(d=>`<div style="margin:4px 0"><button class="btn" onclick="review(${d.id},'${esc(d.original_name)}')">${esc(d.original_name)}</button> ${pill(d.review_status)}</div>`).join('');let action=x.legacy?'<span class="muted">Import legacy records to attach evidence.</span>':`<form class="drop" onsubmit="upload(event,${x.id})"><input name="file" type="file" required accept=".pdf,.png,.jpg,.jpeg,.webp,.doc,.docx,.txt"><button class="btn" type="submit">Upload evidence</button></form>${docs}${String(x.coa_status).toLowerCase()==='approved'?`<button class="btn green" onclick="releaseLot(${x.id})">Release lot</button>`:''}`;return `<tr><td><b>${esc(x.product)}</b><br><span class="muted">${esc(x.vial_size||'')}</span></td><td>${esc(x.lot_code||'—')}<br><span class="muted">${esc(x.sku||'')}</span></td><td>${esc(x.quantity)}</td><td>${pill(x.status)}</td><td>${pill(x.coa_status||'unknown')}</td><td>${action}</td></tr>`}).join(''):`<tr><td colspan="6"><div class="empty">No inventory records are visible yet. Use <b>Recover legacy inventory</b> to scan the existing persistent Jarvis database without deleting anything.</div></td></tr>`}function renderOps(){let o=data.objectives||[],run=o.filter(x=>['running','queued'].includes(x.state)).length,blocked=o.filter(x=>x.state==='blocked').length;$('runtime').innerHTML=`${run} active / queued · ${blocked} blocked`; $('objectives').innerHTML=o.slice(0,6).map(x=>`<div class="event"><b>#${x.id} ${esc(x.title)}</b><small>${esc(x.state)} · step ${esc(x.step)}/${esc(x.max_steps)}</small></div>`).join('')||'<p class="notice">No active objectives.</p>'}function renderEvents(){$('events').innerHTML=(data.events||[]).slice(0,8).map(e=>`<div class="event"><b>${esc(e.title)}</b><div>${esc(e.detail||'')}</div><small>${esc(e.created_at)}</small></div>`).join('')||'<p class="notice">No business events yet.</p>'}async function importLegacy(){if(!confirm('Scan the existing Jarvis database and copy discoverable legacy inventory into the new controlled inventory system? Existing data will not be deleted.'))return;try{let d=await api('/business/inventory/import-legacy',{method:'POST'});alert(`Imported ${d.imported} legacy inventory record(s).`);load()}catch(e){alert(e.message)}}async function upload(ev,id){ev.preventDefault();let f=ev.target.querySelector('input[type=file]').files[0];if(!f)return;let fd=new FormData();fd.append('file',f);fd.append('kind','coa');try{await fetch(`/business/inventory/${id}/documents`,{method:'POST',body:fd}).then(async r=>{let d=await r.json();if(!r.ok)throw new Error(d.detail||'Upload failed');return d});load()}catch(e){alert(e.message)}}function review(id,name){$('reviewText').textContent=`Review ${name}. Approve only after you have verified this is valid supporting evidence for the correct inventory lot.`;$('reviewModal').classList.add('on');$('approveBtn').onclick=()=>reviewDoc(id,true);$('rejectBtn').onclick=()=>reviewDoc(id,false)}function closeModal(){$('reviewModal').classList.remove('on')}async function reviewDoc(id,approved){try{await api(`/business/documents/${id}/review`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({approved})});closeModal();load()}catch(e){alert(e.message)}}async function releaseLot(id){if(!confirm('Release this inventory lot from quarantine? This requires previously approved supporting evidence.'))return;try{await api(`/business/inventory/${id}/release`,{method:'POST'});load()}catch(e){alert(e.message)}}load();setInterval(load,12000)</script></body></html>'''